CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, name TEXT NOT NULL, username TEXT NOT NULL UNIQUE COLLATE NOCASE, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('owner','manager','cashier')), active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts (id INTEGER PRIMARY KEY, address TEXT NOT NULL, username TEXT NOT NULL, created_at TEXT NOT NULL, successful INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS categories (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE COLLATE NOCASE);
CREATE TABLE IF NOT EXISTS stock_items (id INTEGER PRIMARY KEY, name TEXT NOT NULL, unit TEXT NOT NULL, quantity_milli INTEGER NOT NULL DEFAULT 0 CHECK(quantity_milli>=0), min_stock_milli INTEGER NOT NULL DEFAULT 0, avg_cost INTEGER NOT NULL DEFAULT 0, value_minor INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS menu_items (id INTEGER PRIMARY KEY, name TEXT NOT NULL, category_id INTEGER REFERENCES categories(id), price INTEGER NOT NULL CHECK(price>=0), tax_rate REAL NOT NULL DEFAULT 0, description TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS recipes (menu_item_id INTEGER NOT NULL REFERENCES menu_items(id), stock_item_id INTEGER NOT NULL REFERENCES stock_items(id), quantity_milli INTEGER NOT NULL CHECK(quantity_milli>0), PRIMARY KEY(menu_item_id,stock_item_id));
CREATE TABLE IF NOT EXISTS orders (id INTEGER PRIMARY KEY, number TEXT NOT NULL UNIQUE, invoice_number TEXT UNIQUE, status TEXT NOT NULL DEFAULT 'draft', fulfillment_status TEXT NOT NULL DEFAULT 'pending', type TEXT NOT NULL, table_name TEXT NOT NULL DEFAULT '', customer_name TEXT NOT NULL DEFAULT '', customer_phone TEXT NOT NULL DEFAULT '', due_at TEXT, notes TEXT NOT NULL DEFAULT '', tax_enabled INTEGER NOT NULL DEFAULT 1, discount INTEGER NOT NULL DEFAULT 0, subtotal INTEGER NOT NULL DEFAULT 0, tax INTEGER NOT NULL DEFAULT 0, total INTEGER NOT NULL DEFAULT 0, created_by INTEGER REFERENCES users(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, paid_at TEXT, void_reason TEXT);
CREATE TABLE IF NOT EXISTS order_items (id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES orders(id), menu_item_id INTEGER REFERENCES menu_items(id), name TEXT NOT NULL, quantity_milli INTEGER NOT NULL CHECK(quantity_milli>0), sent_milli INTEGER NOT NULL DEFAULT 0, price INTEGER NOT NULL, tax_rate REAL NOT NULL DEFAULT 0, note TEXT NOT NULL DEFAULT '', recipe_snapshot TEXT NOT NULL DEFAULT '[]', line_total INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS kitchen_tickets (id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES orders(id), number TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL, created_by INTEGER REFERENCES users(id));
CREATE TABLE IF NOT EXISTS kitchen_ticket_items (id INTEGER PRIMARY KEY, ticket_id INTEGER NOT NULL REFERENCES kitchen_tickets(id), order_item_id INTEGER REFERENCES order_items(id), name TEXT NOT NULL, quantity_milli INTEGER NOT NULL, note TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS stock_movements (id INTEGER PRIMARY KEY, stock_item_id INTEGER NOT NULL REFERENCES stock_items(id), quantity_milli INTEGER NOT NULL, type TEXT NOT NULL CHECK(type IN ('receive','use','waste','count')), cost_total INTEGER NOT NULL DEFAULT 0, reference TEXT NOT NULL DEFAULT '', order_id INTEGER REFERENCES orders(id), created_by INTEGER REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS payment_accounts (id INTEGER PRIMARY KEY, name TEXT NOT NULL, method TEXT NOT NULL CHECK(method IN ('bank','easypaisa','jazzcash')), details TEXT NOT NULL DEFAULT '', qr_path TEXT, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS payments (id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES orders(id), amount INTEGER NOT NULL CHECK(amount>=0), type TEXT NOT NULL DEFAULT 'payment' CHECK(type IN ('payment','refund')), method TEXT NOT NULL CHECK(method IN ('cash','bank','easypaisa','jazzcash')), payment_account_id INTEGER REFERENCES payment_accounts(id), reference TEXT NOT NULL DEFAULT '', tendered INTEGER, change_due INTEGER NOT NULL DEFAULT 0, reason TEXT NOT NULL DEFAULT '', invoice_refund INTEGER NOT NULL DEFAULT 0, refunded_tax INTEGER NOT NULL DEFAULT 0, created_by INTEGER REFERENCES users(id), created_at TEXT NOT NULL, shift_id INTEGER REFERENCES shifts(id));
CREATE TABLE IF NOT EXISTS financial_requests (request_key TEXT PRIMARY KEY, route TEXT NOT NULL, fingerprint TEXT NOT NULL, order_id INTEGER NOT NULL REFERENCES orders(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS suppliers (id INTEGER PRIMARY KEY, name TEXT NOT NULL, phone TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS expenses (id INTEGER PRIMARY KEY, amount INTEGER NOT NULL CHECK(amount>0), category TEXT NOT NULL, note TEXT NOT NULL DEFAULT '', date TEXT NOT NULL, method TEXT NOT NULL DEFAULT 'cash', created_by INTEGER REFERENCES users(id), created_at TEXT NOT NULL, shift_id INTEGER REFERENCES shifts(id));
CREATE TABLE IF NOT EXISTS shifts (id INTEGER PRIMARY KEY, opened_by INTEGER NOT NULL REFERENCES users(id), closed_by INTEGER REFERENCES users(id), opening_cash INTEGER NOT NULL, counted_cash INTEGER, expected_cash INTEGER, discrepancy INTEGER, note TEXT NOT NULL DEFAULT '', opened_at TEXT NOT NULL, closed_at TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS one_open_shift ON shifts((1)) WHERE closed_at IS NULL;
CREATE TABLE IF NOT EXISTS audit_log (id INTEGER PRIMARY KEY, user_id INTEGER REFERENCES users(id), action TEXT NOT NULL, entity TEXT NOT NULL, entity_id INTEGER, details TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS orders_created ON orders(created_at);
CREATE INDEX IF NOT EXISTS orders_paid ON orders(paid_at);
CREATE INDEX IF NOT EXISTS movements_created ON stock_movements(created_at,stock_item_id);
CREATE INDEX IF NOT EXISTS payments_order ON payments(order_id);
CREATE INDEX IF NOT EXISTS payments_created ON payments(created_at);
CREATE INDEX IF NOT EXISTS order_items_order ON order_items(order_id);
